// ============================================================================
// DOMAIN TYPES & INTERFACES
// ============================================================================
type UserRole = 'guest' | 'staff' | 'manager' | 'admin';

interface UserAccount {
  id: string;
  name: string;
  email: string;
  phone: string;
  role: UserRole;
  accountStatus: 'active' | 'suspended';
  city: string;
  assignedHotelIds: string[];
}

interface SeasonalRule {
  label: string;
  startDate: string;
  endDate: string;
  multiplier: number;
}

interface RoomCategory {
  id: string;
  hotelId: string;
  name: string;
  code: string;
  description: string;
  maxAdults: number;
  maxChildren: number;
  bedConfiguration: string;
  sizeSqFt: number;
  amenities: string[];
  totalInventory: number;
  basePricePerNight: number;
  seasonalPricing: SeasonalRule[];
  image: string;
  isActive: boolean;
}

interface HotelProperty {
  id: string;
  name: string;
  slug: string;
  tagline: string;
  description: string;
  address: string;
  city: string;
  state: string;
  phone: string;
  email: string;
  amenities: string[];
  heroImage: string;
  checkInTime: string;
  checkOutTime: string;
  cancellationWindowHours: number;
  cancellationPenaltyPercent: number;
  taxRatePercent: number;
  ratingAverage: number;
  ratingCount: number;
  startingPrice: number;
  operationalStatus: 'active' | 'maintenance';
  featured: boolean;
}

interface PhysicalRoomUnit {
  id: string;
  hotelId: string;
  roomTypeId: string;
  roomNumber: string;
  floor: number;
  housekeepingStatus: 'inspected' | 'clean' | 'dirty' | 'out_of_service';
  occupancyStatus: 'vacant' | 'occupied' | 'maintenance_block';
  currentBookingRef?: string;
}

type BookingStatus =
  | 'pending_payment'
  | 'confirmed'
  | 'checked_in'
  | 'checked_out'
  | 'cancelled'
  | 'payment_failed';

type PaymentStatus =
  | 'unpaid'
  | 'paid'
  | 'refund_pending'
  | 'partially_refunded'
  | 'refunded'
  | 'failed';

interface BookingRecord {
  id: string;
  bookingReference: string;
  guestId: string;
  guestName: string;
  guestEmail: string;
  guestPhone: string;
  specialRequests: string;
  hotelId: string;
  roomTypeId: string;
  assignedRooms: string[];
  checkInDate: string;
  checkOutDate: string;
  nights: number;
  adults: number;
  children: number;
  roomQuantity: number;
  baseAmount: number;
  taxesAndFees: number;
  additionalCharges: number;
  totalAmount: number;
  status: BookingStatus;
  paymentStatus: PaymentStatus;
  invoiceNumber?: string;
  providerOrderId?: string;
  providerPaymentId?: string;
  eligibleRefundAmount?: number;
  createdAt: string;
  reviewed?: boolean;
}

interface ReviewRecord {
  id: string;
  hotelId: string;
  bookingId: string;
  guestName: string;
  guestCity: string;
  rating: number;
  title: string;
  comment: string;
  createdAt: string;
}

interface ServiceRequestItem {
  id: string;
  hotelId: string;
  roomNumber: string;
  requestType: 'housekeeping' | 'room_service' | 'maintenance' | 'concierge';
  description: string;
  priority: 'low' | 'medium' | 'high' | 'urgent';
  status: 'open' | 'in_progress' | 'resolved';
  assignedStaffName: string;
  createdAt: string;
}

interface NotificationItem {
  id: string;
  recipientId: string;
  title: string;
  message: string;
  isRead: boolean;
  createdAt: string;
  bookingId?: string;
}

interface AuditLogEntry {
  id: string;
  actorName: string;
  actorRole: UserRole;
  action: string;
  resource: string;
  details: string;
  timestamp: string;
}

