const GENERATED_EXTRA_HOTELS: HotelProperty[] = [];
const GENERATED_EXTRA_ROOMS: RoomCategory[] = [];

let nextHotelCounter = 5;
let nextRoomCounter = 6;

for (const citySpec of CITY_CATALOG_SPECS) {
  for (const prop of citySpec.properties) {
    const hId = `htl-${nextHotelCounter}`;
    const slug = `${prop.name}-${citySpec.city}`
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/(^-|-$)/g, '');

    const styleAmenities =
      prop.style === 'palace'
        ? ['Heritage Courtyard Pool', 'Ayurvedic Spa & Hammam', 'Fine Dining & Rooftop Bar', '24-Hour Butler Service', 'High-Speed Wi-Fi']
        : prop.style === 'fort'
        ? ['Narmada River View Terraces', 'Organic Farm-to-Table Dining', 'Heritage Walk & Handloom Tour', 'High-Speed Wi-Fi', 'Airport Chauffeur Transfer']
        : prop.style === 'coastal'
        ? ['Private Plunge Pools', 'Ayurvedic Spa & Hammam', 'Organic Farm-to-Table Dining', 'High-Speed Wi-Fi', 'Complimentary Bicycles']
        : ['Executive Boardrooms', 'Fine Dining & Rooftop Bar', '24-Hour Butler Service', 'High-Speed Wi-Fi', 'EV Charging'];

    const hotelObj: HotelProperty = {
      id: hId,
      name: prop.name,
      slug,
      tagline: prop.tagline,
      description: `${prop.tagline}. Located at ${prop.address} in ${citySpec.city}, ${citySpec.state}, this verified HotelPro property offers curated regional dining, atomic room-inventory guarantees, and full front-desk concierge support.`,
      address: prop.address,
      city: citySpec.city,
      state: citySpec.state,
      phone: `${citySpec.phonePrefix} 240 ${100 + nextHotelCounter}`,
      email: `reservations.${slug.slice(0, 12)}@hotelpro.in`,
      amenities: styleAmenities,
      heroImage: STYLE_IMAGES[prop.style],
      checkInTime: '14:00',
      checkOutTime: '11:00',
      cancellationWindowHours: prop.style === 'palace' ? 72 : 48,
      cancellationPenaltyPercent: 50,
      taxRatePercent: 18,
      ratingAverage: prop.rating,
      ratingCount: prop.reviews,
      startingPrice: prop.basePrice,
      operationalStatus: 'active',
      featured: nextHotelCounter <= 12
    };

    const rm1: RoomCategory = {
      id: `rm-${nextRoomCounter++}`,
      hotelId: hId,
      name: prop.style === 'coastal' ? 'Garden Verandah Pavilion' : 'Heritage Courtyard Chamber',
      code: `HC${nextHotelCounter}`,
      description: `Refined guest chamber at ${prop.name} featuring handcrafted regional timber furnishings, king bed, and rain shower.`,
      maxAdults: 2,
      maxChildren: 1,
      bedConfiguration: '1 King Bed',
      sizeSqFt: 480,
      amenities: ['Courtyard View', 'Rain Shower', 'Espresso Machine', 'High-Speed Wi-Fi'],
      totalInventory: 5,
      basePricePerNight: prop.basePrice,
      seasonalPricing: [
        { label: 'Festive Peak Season (+15%)', startDate: '2026-11-15', endDate: '2026-12-31', multiplier: 1.15 }
      ],
      image: IMG_DELUXE_INTERIOR,
      isActive: true
    };

    const rm2: RoomCategory = {
      id: `rm-${nextRoomCounter++}`,
      hotelId: hId,
      name: prop.style === 'coastal' ? 'Private Plunge Pool Villa Suite' : 'Royal Terrace Heritage Suite',
      code: `RS${nextHotelCounter}`,
      description: `Expansive signature suite at ${prop.name} with private sit-out terrace, separate lounge, and butler service.`,
      maxAdults: 3,
      maxChildren: 2,
      bedConfiguration: '1 Four-Poster King Bed + Daybed',
      sizeSqFt: 790,
      amenities: ['Panoramic Terrace', 'Soaking Tub', '24-Hour Butler Service', 'High-Speed Wi-Fi'],
      totalInventory: 3,
      basePricePerNight: Math.round(prop.basePrice * 1.55),
      seasonalPricing: [
        { label: 'Festive Peak Season (+20%)', startDate: '2026-11-15', endDate: '2026-12-31', multiplier: 1.2 }
      ],
      image: IMG_SUITE_INTERIOR,
      isActive: true
    };

    GENERATED_EXTRA_HOTELS.push(hotelObj);
    GENERATED_EXTRA_ROOMS.push(rm1, rm2);
    nextHotelCounter++;
  }
}

