// ============================================================================
// UTILITY FUNCTIONS
// ============================================================================
function formatINR(amount: number): string {
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0
  }).format(amount || 0);
}

function getNightDates(checkIn: string, checkOut: string): string[] {
  const start = new Date(`${checkIn}T00:00:00Z`);
  const end = new Date(`${checkOut}T00:00:00Z`);
  if (Number.isNaN(start.getTime()) || Number.isNaN(end.getTime()) || end <= start) {
    return [];
  }
  const nights: string[] = [];
  const dayMs = 24 * 60 * 60 * 1000;
  for (let ts = start.getTime(); ts < end.getTime(); ts += dayMs) {
    nights.push(new Date(ts).toISOString().slice(0, 10));
  }
  return nights;
}

function getStatusBadgeStyle(status: BookingStatus | PaymentStatus): string {
  switch (status) {
    case 'confirmed':
    case 'paid':
      return 'bg-emerald-50 text-emerald-700 border-emerald-200';
    case 'checked_in':
      return 'bg-rose-50 text-[#FF385C] border-rose-200';
    case 'pending_payment':
    case 'unpaid':
    case 'refund_pending':
      return 'bg-amber-50 text-amber-700 border-amber-200';
    case 'checked_out':
    case 'refunded':
    case 'partially_refunded':
      return 'bg-neutral-100 text-neutral-700 border-neutral-300';
    case 'cancelled':
    case 'payment_failed':
    case 'failed':
      return 'bg-red-50 text-red-700 border-red-200';
    default:
      return 'bg-neutral-100 text-neutral-700 border-neutral-300';
  }
}

